import{a as e,i as t,r as n,t as r}from"./app-Dkwa1Gla.js";var i=JSON.parse(`{"path":"/%E7%AC%AC08%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E6%95%B4%E5%90%88%E7%AE%A1%E7%90%86/8.2%20%E9%A1%B9%E7%9B%AE%E7%AE%A1%E7%90%86%E8%AE%A1%E5%88%92.html","title":"8.2 项目管理计划","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第08章 项目整合管理/8.2 项目管理计划.md"}`),a={name:`8.2 项目管理计划.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_8-2-项目管理计划" tabindex="-1"><a class="header-anchor" href="#_8-2-项目管理计划"><span>8.2 项目管理计划</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>项目管理计划是指导项目执行、监控和收尾的综合性文件，整合了所有子计划，为项目提供全面的指导。</p><h2 id="项目管理计划的组成" tabindex="-1"><a class="header-anchor" href="#项目管理计划的组成"><span>项目管理计划的组成</span></a></h2><h3 id="_1-范围管理计划" tabindex="-1"><a class="header-anchor" href="#_1-范围管理计划"><span>1. 范围管理计划</span></a></h3><ul><li>定义如何确定和控制项目范围</li><li>包括范围定义、范围验证、范围变更控制</li></ul><h3 id="_2-进度管理计划" tabindex="-1"><a class="header-anchor" href="#_2-进度管理计划"><span>2. 进度管理计划</span></a></h3><ul><li>定义如何制定和控制项目进度</li><li>包括进度计划编制、进度监控、进度控制</li></ul><h3 id="_3-成本管理计划" tabindex="-1"><a class="header-anchor" href="#_3-成本管理计划"><span>3. 成本管理计划</span></a></h3><ul><li>定义如何估算和控制项目成本</li><li>包括成本估算、成本预算、成本控制</li></ul><h3 id="_4-质量管理计划" tabindex="-1"><a class="header-anchor" href="#_4-质量管理计划"><span>4. 质量管理计划</span></a></h3><ul><li>定义如何确保项目质量</li><li>包括质量标准、质量保证、质量控制</li></ul><h3 id="_5-风险管理计划" tabindex="-1"><a class="header-anchor" href="#_5-风险管理计划"><span>5. 风险管理计划</span></a></h3><ul><li>定义如何识别和管理项目风险</li><li>包括风险识别、风险分析、风险应对</li></ul><h3 id="_6-资源管理计划" tabindex="-1"><a class="header-anchor" href="#_6-资源管理计划"><span>6. 资源管理计划</span></a></h3><ul><li>定义如何管理项目资源</li><li>包括人力资源、物资资源、设备资源</li></ul><h3 id="_7-沟通管理计划" tabindex="-1"><a class="header-anchor" href="#_7-沟通管理计划"><span>7. 沟通管理计划</span></a></h3><ul><li>定义如何管理项目沟通</li><li>包括沟通渠道、沟通频率、沟通内容</li></ul><h3 id="_8-采购管理计划" tabindex="-1"><a class="header-anchor" href="#_8-采购管理计划"><span>8. 采购管理计划</span></a></h3><ul><li>定义如何管理项目采购</li><li>包括采购策略、采购流程、合同管理</li></ul><h3 id="_9-干系人管理计划" tabindex="-1"><a class="header-anchor" href="#_9-干系人管理计划"><span>9. 干系人管理计划</span></a></h3><ul><li>定义如何管理项目干系人</li><li>包括干系人识别、干系人沟通、干系人参与</li></ul><h3 id="_10-变更管理计划" tabindex="-1"><a class="header-anchor" href="#_10-变更管理计划"><span>10. 变更管理计划</span></a></h3><ul><li>定义如何管理项目变更</li><li>包括变更流程、变更审批、变更控制</li></ul><h2 id="项目管理计划的制定过程" tabindex="-1"><a class="header-anchor" href="#项目管理计划的制定过程"><span>项目管理计划的制定过程</span></a></h2><h3 id="_1-收集输入" tabindex="-1"><a class="header-anchor" href="#_1-收集输入"><span>1. 收集输入</span></a></h3><ul><li>项目章程</li><li>组织过程资产</li><li>事业环境因素</li></ul><h3 id="_2-制定子计划" tabindex="-1"><a class="header-anchor" href="#_2-制定子计划"><span>2. 制定子计划</span></a></h3><ul><li>各知识领域制定相应的子计划</li><li>确保子计划之间协调一致</li></ul><h3 id="_3-整合计划" tabindex="-1"><a class="header-anchor" href="#_3-整合计划"><span>3. 整合计划</span></a></h3><ul><li>将各子计划整合为综合计划</li><li>检查计划的完整性和一致性</li></ul><h3 id="_4-评审批准" tabindex="-1"><a class="header-anchor" href="#_4-评审批准"><span>4. 评审批准</span></a></h3><ul><li>组织相关方评审</li><li>获得批准后正式发布</li></ul><h2 id="项目管理计划的更新" tabindex="-1"><a class="header-anchor" href="#项目管理计划的更新"><span>项目管理计划的更新</span></a></h2><h3 id="更新时机" tabindex="-1"><a class="header-anchor" href="#更新时机"><span>更新时机</span></a></h3><ul><li>项目范围变更</li><li>项目进度调整</li><li>项目成本变化</li><li>其他重大变更</li></ul><h3 id="更新流程" tabindex="-1"><a class="header-anchor" href="#更新流程"><span>更新流程</span></a></h3><ul><li>提出更新请求</li><li>评估更新影响</li><li>获得批准后更新</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>项目管理计划的组成</strong></li><li><strong>各子计划的作用</strong></li><li><strong>项目管理计划的制定过程</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>范围进度成本质量风险资源沟通采购干系人变更，十大子计划要记全</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：项目管理计划不包括以下哪个子计划？ A. 范围管理计划 B. 进度管理计划 C. 人员管理计划 D. 风险管理计划</p><p><strong>答案</strong>：C</p><p><strong>解析</strong>：项目管理计划包括范围管理计划、进度管理计划、成本管理计划、质量管理计划、风险管理计划、资源管理计划、沟通管理计划、采购管理计划、干系人管理计划和变更管理计划。人员管理计划通常包含在资源管理计划中，不是独立的子计划。</p>`,46)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};